//! `/api/v1/agents` (src/controllers/api_v1_agents.rs). Generated by `cargo offrails generate api agents`.
//! The request matrix per endpoint (api.md#testing): happy path, 422 with the exact body, 401 without
//! a token, 404 for another user's record, 403 for a read-only token.
//! APP: cite each acceptance criterion (`/// AC-agents-1`) on the test that proves it.

use axum::http::StatusCode;
use board::models::agent;
use board::routes::paths;
use serde_json::{Value, json};

use crate::factories;
use crate::support::TestApp;

/// The JSON a client would send for these (valid) params.
fn body(params: &agent::AgentParams) -> Value {
    json!({
        "name": params.name.clone(),
        "description": params.description.clone(),
    })
}

fn bearer(token: &str) -> String {
    format!("Bearer {token}")
}

#[tokio::test]
async fn index_lists_only_the_token_users_agents_with_page_info() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    let them = factories::user(app.db(), "them@example.com").await;
    let mine = factories::agent(app.db(), &me).await;
    let theirs = factories::agent(app.db(), &them).await;
    let token = app.api_token_for(&me, false).await;
    let res = app
        .send_json(
            "GET",
            &paths::api_agents(),
            None,
            &[("authorization", bearer(&token).as_str())],
        )
        .await;
    res.assert_ok();
    let page: Value = res.json();
    let ids: Vec<i64> = page["data"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| r["id"].as_i64().unwrap())
        .collect();
    assert_eq!(ids, vec![mine.id]);
    assert!(!ids.contains(&theirs.id));
    assert_eq!(
        page["page"],
        json!({ "page": 1, "per": 25, "has_more": false })
    );
}

/// SECURITY: no token, no data.
#[tokio::test]
async fn every_endpoint_needs_a_token() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    let record = factories::agent(app.db(), &me).await;
    for (method, path) in [
        ("GET", paths::api_agents()),
        ("POST", paths::api_agents()),
        ("GET", paths::api_agent(record.id)),
        ("PATCH", paths::api_agent(record.id)),
        ("DELETE", paths::api_agent(record.id)),
    ] {
        app.send_json(method, &path, Some(&json!({})), &[])
            .await
            .assert_status(StatusCode::UNAUTHORIZED);
    }
}

#[tokio::test]
async fn show_returns_the_agent_and_404s_a_missing_one() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    let record = factories::agent(app.db(), &me).await;
    let token = app.api_token_for(&me, false).await;
    let bearer = bearer(&token);
    let auth = [("authorization", bearer.as_str())];
    let res = app
        .send_json("GET", &paths::api_agent(record.id), None, &auth)
        .await;
    res.assert_ok();
    assert_eq!(res.json::<Value>()["data"]["id"], json!(record.id));
    let res = app
        .send_json("GET", &paths::api_agent(record.id + 1000), None, &auth)
        .await;
    res.assert_status(StatusCode::NOT_FOUND);
    assert_eq!(res.json::<Value>(), json!({ "error": "not_found" }));
}

#[tokio::test]
async fn create_is_201_with_the_body_and_saves_it() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    let token = app.api_token_for(&me, true).await;
    let params = factories::agent_params(app.db(), &me).await;
    let res = app
        .send_json(
            "POST",
            &paths::api_agents(),
            Some(&body(&params)),
            &[("authorization", bearer(&token).as_str())],
        )
        .await;
    res.assert_status(StatusCode::CREATED);
    let id = res.json::<Value>()["data"]["id"].as_i64().unwrap();
    let saved = factories::reload_agent(app.db(), id).await.expect("saved");
    assert_eq!(saved.user_id, me.id);
}

/// SECURITY: a read-only token can't write anything.
#[tokio::test]
async fn a_read_only_token_cant_write() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    let record = factories::agent(app.db(), &me).await;
    let token = app.api_token_for(&me, false).await;
    let params = factories::agent_params(app.db(), &me).await;
    let auth = bearer(&token);
    for (method, path) in [
        ("POST", paths::api_agents()),
        ("PATCH", paths::api_agent(record.id)),
        ("DELETE", paths::api_agent(record.id)),
    ] {
        app.send_json(
            method,
            &path,
            Some(&body(&params)),
            &[("authorization", auth.as_str())],
        )
        .await
        .assert_status(StatusCode::FORBIDDEN);
    }
    assert_eq!(
        factories::reload_agent(app.db(), record.id).await,
        Some(record)
    );
}

#[tokio::test]
async fn a_body_that_isnt_json_is_a_422() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    let token = app.api_token_for(&me, true).await;
    let res = app
        .send_json(
            "POST",
            &paths::api_agents(),
            Some(&json!("not an object")),
            &[("authorization", bearer(&token).as_str())],
        )
        .await;
    res.assert_status(StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(
        res.json::<Value>(),
        json!({ "errors": { "body": ["is not valid JSON"] } })
    );
}

#[tokio::test]
async fn invalid_input_is_a_422_with_the_errors() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    let token = app.api_token_for(&me, true).await;
    let mut params = factories::agent_params(app.db(), &me).await;
    params.name = String::new();
    let res = app
        .send_json(
            "POST",
            &paths::api_agents(),
            Some(&body(&params)),
            &[("authorization", bearer(&token).as_str())],
        )
        .await;
    res.assert_status(StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(
        res.json::<Value>()["errors"]["name"],
        json!(["can't be blank"])
    );
}

#[tokio::test]
async fn update_changes_what_was_sent_and_destroy_is_204() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    let record = factories::agent(app.db(), &me).await;
    let token = app.api_token_for(&me, true).await;
    let auth = bearer(&token);
    let res = app
        .send_json(
            "PATCH",
            &paths::api_agent(record.id),
            Some(&json!({ "name": "Changed" })),
            &[("authorization", auth.as_str())],
        )
        .await;
    res.assert_ok();
    assert_eq!(res.json::<Value>()["data"]["name"], json!("Changed"));
    app.send_json(
        "DELETE",
        &paths::api_agent(record.id),
        None,
        &[("authorization", auth.as_str())],
    )
    .await
    .assert_status(StatusCode::NO_CONTENT);
    assert!(factories::reload_agent(app.db(), record.id).await.is_none());
}

/// SECURITY: another user's agent is 404 for every method (it looks missing), and stays as it was.
#[tokio::test]
async fn another_users_agent_is_404() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    let them = factories::user(app.db(), "them@example.com").await;
    let theirs = factories::agent(app.db(), &them).await;
    let token = app.api_token_for(&me, true).await;
    let auth = bearer(&token);
    let params = factories::agent_params(app.db(), &me).await;
    for method in ["GET", "PATCH", "DELETE"] {
        app.send_json(
            method,
            &paths::api_agent(theirs.id),
            Some(&body(&params)),
            &[("authorization", auth.as_str())],
        )
        .await
        .assert_status(StatusCode::NOT_FOUND);
    }
    assert_eq!(
        factories::reload_agent(app.db(), theirs.id).await,
        Some(theirs)
    );
}
